class Solution {
public:
    int medianOfUniquenessArray(vector<int>& nums) {
        int n = nums.size();
        long long T = (long long)n * (n + 1) / 2;
        long long k = (T + 1) / 2;
        auto countLE = [&](long long v) {
            unordered_map<int,int> cnt;
            int distinct = 0, left = 0;
            long long total = 0;
            for (int right = 0; right < n; right++) {
                if (cnt[nums[right]]++ == 0) distinct++;
                while (distinct > v) {
                    if (--cnt[nums[left]] == 0) distinct--;
                    left++;
                }
                total += right - left + 1;
            }
            return total;
        };
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (countLE(mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

