class Solution {
    public int medianOfUniquenessArray(int[] nums) {
        int n = nums.length;
        long T = (long) n * (n + 1) / 2;
        long k = (T + 1) / 2;
        java.util.function.LongUnaryOperator countLE = v -> {
            Map<Integer,Integer> cnt = new HashMap<>();
            int distinct = 0, left = 0;
            long total = 0;
            for (int right = 0; right < n; right++) {
                if (cnt.merge(nums[right], 1, Integer::sum) == 1) distinct++;
                while (distinct > v) {
                    if (cnt.merge(nums[left], -1, Integer::sum) == 0) distinct--;
                    left++;
                }
                total += right - left + 1;
            }
            return total;
        };
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (countLE.applyAsLong(mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

