    const n = nums.length;
    const T = n * (n + 1) / 2;
    const k = Math.floor((T + 1) / 2);
    const countLE = v => {
        const cnt = new Map();
        let distinct = 0, left = 0, total = 0;
        for (let right = 0; right < n; right++) {
            const x = nums[right];
            cnt.set(x, (cnt.get(x) || 0) + 1);
            if (cnt.get(x) === 1) distinct++;
            while (distinct > v) {
                const y = nums[left++];
                cnt.set(y, cnt.get(y) - 1);
                if (cnt.get(y) === 0) distinct--;
            }
            total += right - left + 1;
        }
        return total;
    };
    let lo = 1, hi = n;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (countLE(mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
};

