class Solution:
    def medianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        T = n * (n + 1) // 2
        k = (T + 1) // 2
        def countLE(v):
            cnt = defaultdict(int)
            distinct = 0
            total = 0
            left = 0
            for right, x in enumerate(nums):
                cnt[x] += 1
                if cnt[x] == 1: distinct += 1
                while distinct > v:
                    cnt[nums[left]] -= 1
                    if cnt[nums[left]] == 0: distinct -= 1
                    left += 1
                total += right - left + 1
            return total
        return min(v for v in range(1, n + 1) if countLE(v) >= k)

